import random
from typing import List

# This generator produces valid and interesting binary file contents for
# functions dealing with BOM detection, Unicode checks, and DOS->UNIX
# conversion. It focuses on realistic encodings, varied newlines, and
# edge-case compositions while remaining valid.

MAX_SIZE = 4096

# Predefined text snippets to combine (ASCII-safe bytes)
ASCII_SNIPPETS = [
    b"Hello, world!",
    b"The quick brown fox jumps over the lazy dog.",
    b"Lorem ipsum dolor sit amet, consectetur adipiscing elit.",
    b"1234567890",
    b"Tabs\tand\tspaces",
    b"Carriage\rReturn",
    b"Line\nFeed",
    b"Windows\r\nNewlines",
    b"Mixed end of line: LF\nCR\rCRLF\r\n",
]

# Safe UTF-8 snippets; avoid embedding literal NULs in source
UTF8_SNIPPETS = [
    "Café naïve résumé".encode("utf-8"),
    "中文字符测试".encode("utf-8"),
    "日本語のテキスト".encode("utf-8"),
    "🙂🙃😉 emoji sequence".encode("utf-8"),
    "Grüße, nächster Zeile".encode("utf-8"),
]

# DOS line endings focus: lines ending with CRLF, plus some LF-only and CR-only
DOS_LINES = [
    b"line1\r\n",
    b"line2 with spaces   \r\n",
    b"line3 with tab\t\r\n",
    b"line4 end\r\n",
]

# BOM sequences
BOM_NONE = b""
BOM_UTF8 = b"\xEF\xBB\xBF"
BOM_UTF16LE = b"\xFF\xFE"
BOM_UTF16BE = b"\xFE\xFF"
BOM_UTF32LE = b"\xFF\xFE\x00\x00"
BOM_UTF32BE = b"\x00\x00\xFE\xFF"


def _rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))


def _make_utf16_from_utf8(utf8_data: bytes, be: bool, with_crlf_pattern: bool, r: random.Random) -> bytes:
    # Decode to str, then encode to UTF-16LE/BE without BOM
    try:
        s = utf8_data.decode("utf-8", errors="strict")
    except Exception:
        # Fallback: interpret as latin-1 to keep data valid
        s = utf8_data.decode("latin-1", errors="ignore")
    if with_crlf_pattern:
        # intersperse CRLF and LF
        parts = s.split("\n")
        rebuilt = []
        for i, p in enumerate(parts):
            rebuilt.append(p)
            if i < len(parts) - 1:
                rebuilt.append("\r\n" if r.random() < 0.6 else "\n")
        s = "".join(rebuilt)
    enc = "utf-16-be" if be else "utf-16-le"
    return s.encode(enc)


def _make_utf32_from_utf8(utf8_data: bytes, be: bool, r: random.Random) -> bytes:
    try:
        s = utf8_data.decode("utf-8", errors="strict")
    except Exception:
        s = utf8_data.decode("latin-1", errors="ignore")
    enc = "utf-32-be" if be else "utf-32-le"
    return s.encode(enc)


def _mix_newlines(data: bytes, r: random.Random) -> bytes:
    # Replace a fraction of LFs with CRLF and some with CR
    out = bytearray()
    i = 0
    while i < len(data):
        b = data[i]
        if b == 0x0A and (i == 0 or data[i - 1] != 0x0D):
            p = r.random()
            if p < 0.5:
                out.extend(b"\r\n")
            elif p < 0.7:
                out.append(0x0D)
            else:
                out.append(0x0A)
            i += 1
        else:
            out.append(b)
            i += 1
    return bytes(out)


def _gen_ascii_block(r: random.Random) -> bytes:
    lines = []
    # Mix curated snippets and random ASCII
    for _ in range(r.randint(2, 6)):
        choice = r.randint(0, 2)
        if choice == 0 and ASCII_SNIPPETS:
            lines.append(r.choice(ASCII_SNIPPETS))
        elif choice == 1 and DOS_LINES:
            lines.append(r.choice(DOS_LINES))
        else:
            ln = r.randint(5, 80)
            # Printable ASCII plus whitespace/newline controls
            charset = b" .,_-+/\\|()[]{}\t\r\n" + bytes(range(0x20, 0x7F))
            rand_line = bytes(r.choice(list(charset)) for _ in range(ln))
            lines.append(rand_line + (b"\n" if r.random() < 0.7 else b"\r\n"))
    data = b"".join(lines)
    if r.random() < 0.6:
        data = _mix_newlines(data, r)
    return data


def _safe_utf8_from_codepoints(cps: List[int]) -> bytes:
    # Filter out surrogate range to avoid encode errors
    filtered = []
    for c in cps:
        if 0xD800 <= c <= 0xDFFF:
            continue
        if c > 0x10FFFF or c < 0:
            continue
        filtered.append(c)
    s = "".join(chr(c) for c in filtered)
    return s.encode("utf-8")


def _gen_utf8_block(r: random.Random) -> bytes:
    pieces: List[bytes] = []
    for _ in range(r.randint(2, 6)):
        mode = r.randint(0, 3)
        if mode == 0:
            pieces.append(r.choice(UTF8_SNIPPETS))
        elif mode == 1:
            # random valid UTF-8 sequence from code points (avoid surrogates)
            cp_count = r.randint(5, 40)
            cps = []
            for _ in range(cp_count):
                zone = r.random()
                if zone < 0.6:
                    cps.append(r.randint(0x20, 0x7E))
                elif zone < 0.8:
                    cps.append(r.randint(0x80, 0x7FF))
                elif zone < 0.95:
                    val = r.randint(0x800, 0xFFFF)
                    # Avoid surrogates explicitly
                    if 0xD800 <= val <= 0xDFFF:
                        val = 0xE000 + (val - 0xD800) % (0xFFFF - 0xE000 + 1)
                    cps.append(val)
                else:
                    cps.append(r.randint(0x10000, 0x10FFFF))
            pieces.append(_safe_utf8_from_codepoints(cps))
        elif mode == 2:
            pieces.append(r.choice(ASCII_SNIPPETS))
        else:
            # sprinkle newlines
            pieces.append(b"\r\n" if r.random() < 0.5 else b"\n")
    data = b"".join(pieces)
    if r.random() < 0.6:
        data = _mix_newlines(data, r)
    return data


def _apply_bom_and_encoding(core: bytes, bom_name: str, r: random.Random) -> bytes:
    # For UTF-16/32, convert content to that endian without BOM, then prepend BOM
    if bom_name == "none":
        return core
    if bom_name == "utf8":
        return BOM_UTF8 + core
    if bom_name == "utf16le":
        body = _make_utf16_from_utf8(core, be=False, with_crlf_pattern=r.random() < 0.5, r=r)
        return BOM_UTF16LE + body
    if bom_name == "utf16be":
        body = _make_utf16_from_utf8(core, be=True, with_crlf_pattern=r.random() < 0.5, r=r)
        return BOM_UTF16BE + body
    if bom_name == "utf32le":
        body = _make_utf32_from_utf8(core, be=False, r=r)
        return BOM_UTF32LE + body
    if bom_name == "utf32be":
        body = _make_utf32_from_utf8(core, be=True, r=r)
        return BOM_UTF32BE + body
    return core


def _maybe_truncate(data: bytes, r: random.Random) -> bytes:
    # Keep within MAX_SIZE and sometimes cut mid-line to test last-line EOL handling
    maxlen = min(MAX_SIZE, len(data))
    if len(data) > MAX_SIZE or r.random() < 0.2:
        cut = r.randint(max(1, maxlen // 2), maxlen) if maxlen > 1 else 1
        return data[:cut]
    return data


def _maybe_append_final_eol(data: bytes, r: random.Random) -> bytes:
    if r.random() < 0.5:
        return data
    # Sometimes ensure last line has EOL, sometimes not
    if r.random() < 0.5:
        return data + (b"\r\n" if r.random() < 0.5 else b"\n")
    return data


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose core generator: ASCII vs UTF-8 focused, and optionally pure DOS lines
    mode = r.randint(0, 2)
    if mode == 0:
        core = _gen_ascii_block(r)
    elif mode == 1:
        core = _gen_utf8_block(r)
    else:
        # DOS-heavy file with CRLF lines
        lines = []
        for _ in range(r.randint(3, 30)):
            content_choice = r.randint(0, 3)
            if content_choice == 0:
                line = r.choice(ASCII_SNIPPETS)
            elif content_choice == 1:
                line = r.choice(UTF8_SNIPPETS)
            elif content_choice == 2:
                # random printable
                ln = r.randint(1, 120)
                charset = b" .,_-+/\\|()[]{}\t" + bytes(range(0x20, 0x7F))
                line = bytes(r.choice(list(charset)) for _ in range(ln))
            else:
                # include a binary byte burst occasionally (encoded as hex to be text-safe)
                burst = _rand_bytes(r, r.randint(0, 8))
                line = b"BIN:" + burst.hex().encode("ascii")
            lines.append(line + b"\r\n")
        core = b"".join(lines)

    # Pick a BOM strategy with bias toward common cases
    bom_weights = [
        ("none", 0.35),
        ("utf8", 0.25),
        ("utf16le", 0.15),
        ("utf16be", 0.1),
        ("utf32le", 0.1),
        ("utf32be", 0.05),
    ]
    roll = r.random()
    acc = 0.0
    bom_choice = "none"
    for name, w in bom_weights:
        acc += w
        if roll <= acc:
            bom_choice = name
            break

    data = _apply_bom_and_encoding(core, bom_choice, r)

    # Optionally prepend or append small random binary chunks to ensure binary-safe paths
    if r.random() < 0.2:
        data = _rand_bytes(r, r.randint(1, 8)) + data
    if r.random() < 0.2:
        data = data + _rand_bytes(r, r.randint(1, 8))

    data = _maybe_append_final_eol(data, r)
    data = _maybe_truncate(data, r)

    # Ensure not empty
    if not data:
        data = b"\n"

    # Bound final size
    if len(data) > MAX_SIZE:
        data = data[:MAX_SIZE]

    return data

import random
import string
from typing import List

# We generate interesting arbitrary C strings for d2u_strncpy's src argument.
# The fuzzer stub also uses an unsigned int to select dest_size; we cannot set that directly,
# but providing a src whose length exercises edge cases relative to common sizes helps.
# We will return a bytes object representing a single string to feed FUZZ_PARAM_STR/FILENAME.
# Strategy: randomly choose among patterns, include ASCII, extended bytes, UTF-8 sequences,
# long runs, embedded NUL avoided, and boundary lengths like 0, 1, 2, 255, 256, 1024, etc.

MAX_OUT = 4096

ASCII_PRINT = string.ascii_letters + string.digits + string.punctuation + " "

# Some useful multibyte UTF-8 sequences (valid)
UTF8_SEQS = [
    "€",              # 3-byte
    "𐍈",             # 4-byte
    "®",              # 2-byte
    "✓",              # 3-byte
    "汉字",           # 3-byte each
    "😀",             # 4-byte
]

# Some Windows/DOS special bytes excluding NUL
CTRL_BYTES = bytes([0x07, 0x08, 0x09, 0x0A, 0x0D, 0x1B])  # BEL, BS, TAB, LF, CR, ESC


def _rand_ascii(r: random.Random, n: int) -> str:
    return "".join(r.choice(ASCII_PRINT) for _ in range(n))


def _rand_bytes_excluding_nul(r: random.Random, n: int) -> bytes:
    # choose from 1..255 excluding 0
    return bytes(r.randrange(1, 256) for _ in range(n))


def _mix_utf8(r: random.Random, target_len: int) -> str:
    parts: List[str] = []
    while len("".join(parts).encode("utf-8")) < target_len:
        choice = r.randrange(5)
        if choice == 0:
            parts.append(_rand_ascii(r, r.randrange(1, 8)))
        elif choice == 1:
            parts.append(r.choice(UTF8_SEQS))
        elif choice == 2:
            parts.append("\r\n" if r.random() < 0.5 else "\n")
        elif choice == 3:
            parts.append("\t" * r.randrange(1, 4))
        else:
            # add some high bytes via latin-1 mapping
            b = _rand_bytes_excluding_nul(r, r.randrange(1, 5))
            parts.append(b.decode('latin-1', 'ignore'))
    s = "".join(parts)
    # trim to approximately target_len bytes when UTF-8-encoded
    b = s.encode('utf-8')
    if len(b) > target_len:
        b = b[:target_len]
        # ensure we don't cut in the middle of multibyte; back up to valid boundary
        while True:
            try:
                s = b.decode('utf-8')
                break
            except UnicodeDecodeError:
                b = b[:-1]
    return s


def _make_pattern(r: random.Random) -> bytes:
    # Choose scenario to hit boundary conditions for strncpy-like semantics
    scenario = r.randrange(10)

    if scenario == 0:
        # Empty string
        s = ""
    elif scenario == 1:
        # Single char
        s = r.choice(ASCII_PRINT)
    elif scenario == 2:
        # Exactly 255 ASCII chars
        s = _rand_ascii(r, 255)
    elif scenario == 3:
        # 256 ASCII chars
        s = _rand_ascii(r, 256)
    elif scenario == 4:
        # CRLF heavy
        runs = ["CRLF\r\n" * r.randrange(1, 50), "LF\n" * r.randrange(1, 50)]
        s = "".join(r.sample(runs, k=len(runs)))
    elif scenario == 5:
        # Tabs and spaces, leading/trailing whitespace
        s = (" " * r.randrange(0, 10)) + ("\t" * r.randrange(0, 10)) + _rand_ascii(r, r.randrange(10, 60)) + ("\t" * r.randrange(0, 10)) + (" " * r.randrange(0, 10))
    elif scenario == 6:
        # Mixed UTF-8
        s = _mix_utf8(r, r.randrange(40, 300))
    elif scenario == 7:
        # High bytes only (latin-1), no NUL
        b = _rand_bytes_excluding_nul(r, r.randrange(20, 200))
        s = b.decode('latin-1', 'ignore')
    elif scenario == 8:
        # Control characters sprinkled
        base = _rand_ascii(r, r.randrange(20, 100))
        insert_count = r.randrange(5, 20)
        bl = list(base)
        for _ in range(insert_count):
            pos = r.randrange(0, len(bl)+1)
            bl[pos:pos] = chr(r.choice(list(CTRL_BYTES))),
        s = "".join(bl)
    else:
        # Long run up to limit
        target = r.randrange(512, min(2048, MAX_OUT-1))
        s = _mix_utf8(r, target)

    # Ensure no embedded NULs; if present due to decoding quirks, strip them
    s = s.replace("\x00", "")
    b = s.encode('utf-8')
    if len(b) > MAX_OUT - 1:
        b = b[:MAX_OUT - 1]
        # try to keep valid UTF-8
        while True:
            try:
                s = b.decode('utf-8')
                break
            except UnicodeDecodeError:
                b = b[:-1]
    return s.encode('utf-8')


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    return _make_pattern(r)
